  /* DO NOT REMOVE THE COMMENT BELOW!!! */
class AudioPlayer {
	constructor(audioContext, rate){
		let sources = [];
		let samples = 0;
		const baseTime = audioContext.currentTime;

		this.frames = rate / 100;
		this.paused = true;
		this._shutdown = false;
		this.onbuffer = ()=>{};
		this.onended = ()=>{};

		const read = ()=>{
			const audioBuffer = audioContext.createBuffer(2, this.frames, rate);

			if(!this.paused){
				this.onbuffer(audioBuffer, this.frames);
			}

			const currentSource = audioContext.createBufferSource();
			currentSource.buffer = audioBuffer;
			currentSource.connect(audioContext.destination);

			currentSource.onended = ()=>{
				sources = sources.filter((x)=>x != currentSource);

				if(this._shutdown){
					if(sources.length == 0) this.onended();
					return;
				}

				for(let i = sources.length; i < 5; i++) read();
			}

			sources.push(currentSource);

			currentSource.start(baseTime + samples / rate);

			samples += this.frames;
		}

		read();
		read();
		read();
		read();
		read();
	}

	resume(){
		this.paused = false;
	}

	pause(){
		this.paused = true;
	}

	shutdown(){
		this._shutdown = true;
	}
};

  if (embedded) {
    loaded.AudioPlayer = AudioPlayer; // eslint-disable-line
  } else {
    loaded.AudioPlayer = await Scratch.external.evalAndReturn(
      "https://raw.githubusercontent.com/pyrite-dev/pmidi/42a8c0657b71c54a59a2a7bc0f74e74907afa24d/web/audioplayer.js",
      "AudioPlayer"
    );
  }

